) on commit drop;

insert into editorial_scope_correction_v1 values
  ('JED','ar','نقل الأثاث والبضائع من الرياض إلى جدة | نقلك','اطلب نقل أثاث أو بضائع مؤهلة من الرياض إلى جدة، مع مراجعة الحمولة والعنوانين والوصول قبل إرسال عرض سعر واضح من نقلك.','نقل الأثاث والبضائع من الرياض إلى جدة','في النطاق التجاري المعتمد للإطلاق، تظهر جدة كوجهة مفعلة للطلبات المؤهلة التي يبدأ استلامها من الرياض. تخدم نقلك طلبات النقل المؤهلة في جدة بمسار يبدأ من معلومات عملية لا من وعود عامة. يحدد العميل موقع الاستلام والتسليم وطبيعة الأثاث أو البضائع وموعده المفضل، ثم يراجع الفريق البيانات ليقترح ترتيباً قابلاً للتنفيذ وعرض سعر واضحاً.','يدعم المسار نقل الأثاث والبضائع العامة المؤهلة من الرياض إلى جدة. يمكن طلب التغليف أو التحميل والتنزيل، لكن تأكيدها يعتمد على مراجعة الحمولة والعنوانين والتوفر. النقل المحلي الذي يقع طرفاه داخل جدة ليس ضمن نطاق الإطلاق المعلن حالياً، ولا تقدم الصفحة وعداً بخلاف ذلك.','تُقيّم العناوين في جدة حسب الموقع الفعلي وسهولة الوصول ومساحة توقف المركبة، لذلك لا تفترض الصفحة تغطية كل حي أو صلاحية كل عنوان قبل المراجعة.','[{"question":"هل يمكن طلب نقل من الرياض إلى جدة؟","answer":"نعم، يمكن إرسال طلب مؤهل يبدأ من الرياض ويتجه إلى جدة. يعتمد التأكيد على نوع المنقولات والعنوانين والموعد وتوفر الموارد بعد المراجعة.","displayOrder":10},{"question":"هل يتضمن نطاق الإطلاق النقل المحلي داخل جدة؟","answer":"لا. النقل المحلي المعلن حالياً مخصص للطلبات التي يقع طرفاها في الرياض. تظهر جدة كوجهة مفعلة للطلبات المؤهلة المنطلقة من الرياض.","displayOrder":20},{"question":"هل يمكن إضافة التغليف لطلب متجه إلى جدة؟","answer":"يمكن اختيار التغليف عند تقديم الطلب المتجه إلى جدة. يراجع الفريق عدد القطع وطبيعتها، ولا يُدرج الدعم إلا كبند واضح في عرض السعر المعتمد.","displayOrder":30}]'::jsonb),
  ('JED','en','Furniture and Goods Transport from Riyadh to Jeddah | Naqlk','Request eligible furniture or goods transport from Riyadh to Jeddah, with cargo, addresses, and access reviewed before Naqlk issues a clear quotation.','Furniture and goods transport from Riyadh to Jeddah','In the approved launch scope, Jeddah is an enabled destination for eligible requests with pickup in Riyadh. Naqlk handles eligible Jeddah transport requests through a practical review rather than a generic promise. Customers identify the pickup and delivery points, describe the furniture or goods, and provide a preferred date so the team can assess the request and prepare a clear quotation.','The flow supports eligible furniture and general-goods transport from Riyadh to Jeddah. Packing and loading or unloading may be requested, subject to cargo, address, and availability review. A local journey with both endpoints inside Jeddah is not in the currently published launch scope, and this page does not claim otherwise.','Jeddah addresses are assessed individually for location accuracy, vehicle access, and a workable stopping point. The page does not imply that every district or property is automatically serviceable.','[{"question":"Can I request transport from Riyadh to Jeddah?","answer":"Yes. You can submit an eligible request originating in Riyadh and going to Jeddah. Confirmation depends on the cargo, addresses, date, and resources after review.","displayOrder":10},{"question":"Does the launch scope include local transport within Jeddah?","answer":"No. The published local service currently applies when both endpoints are in Riyadh. Jeddah is enabled as a destination for eligible requests originating in Riyadh.","displayOrder":20},{"question":"Can packing be added to a request going to Jeddah?","answer":"Packing can be selected for the Jeddah request. The team reviews the items and includes support only as a clear line in the approved quotation.","displayOrder":30}]'::jsonb),
  ('MKK','ar','تنظيم طلب نقل من الرياض إلى مكة المكرمة | نقلك','نظّم رحلة نقل مؤهلة من الرياض إلى مكة المكرمة عبر نقلك، وأضف تفاصيل المنقولات والخدمات الاختيارية ليُراجع الفريق الطلب قبل التسعير.','تنظيم رحلة النقل من الرياض إلى مكة المكرمة','في النطاق التجاري المعتمد للإطلاق، تظهر مكة المكرمة كوجهة مفعلة للطلبات المؤهلة التي يبدأ استلامها من الرياض. في مكة المكرمة تتأثر خطة النقل بدقة العنوان ووقت الوصول وطبيعة المبنى بقدر تأثرها بنوع المنقولات. يتيح نموذج نقلك جمع هذه التفاصيل في طلب واحد، ثم يراجعها فريق المبيعات لتحديد ما إذا كانت الخدمة والموعد المطلوبان قابلين للتنفيذ.','يدعم المسار نقل الأثاث والبضائع العامة المؤهلة من الرياض إلى مكة المكرمة. يمكن طلب التغليف أو التحميل والتنزيل، لكن تأكيدها يعتمد على مراجعة الحمولة والعنوانين والتوفر. النقل المحلي الذي يقع طرفاه داخل مكة المكرمة ليس ضمن نطاق الإطلاق المعلن حالياً، ولا تقدم الصفحة وعداً بخلاف ذلك.','لا تُفترض قابلية الوصول إلى كل موقع في مكة المكرمة. يفيد إدخال اسم الشارع ووصف المدخل والطابق وأقرب معلم في تقييم العنوان وتجنب معلومات تغطية مضللة.','[{"question":"هل يمكن طلب نقل من الرياض إلى مكة المكرمة؟","answer":"نعم، يمكن إرسال طلب مؤهل يبدأ من الرياض ويتجه إلى مكة المكرمة. يعتمد التأكيد على نوع المنقولات والعنوانين والموعد وتوفر الموارد بعد المراجعة.","displayOrder":10},{"question":"هل يتضمن نطاق الإطلاق النقل المحلي داخل مكة المكرمة؟","answer":"لا. النقل المحلي المعلن حالياً مخصص للطلبات التي يقع طرفاها في الرياض. تظهر مكة المكرمة كوجهة مفعلة للطلبات المؤهلة المنطلقة من الرياض.","displayOrder":20},{"question":"كيف أحصل على عرض سعر لرحلة إلى مكة المكرمة؟","answer":"أدخل عنوان الاستلام في الرياض وعنوان التسليم في مكة المكرمة ووصف المنقولات والموعد. يراجع ممثل المبيعات البيانات قبل إرسال عرض مفصل.","displayOrder":30}]'::jsonb),
  ('MKK','en','Plan a Transport Request from Riyadh to Makkah | Naqlk','Organize an eligible Riyadh-to-Makkah journey, adding item and optional-service details for team review before pricing.','Plan a transport journey from Riyadh to Makkah','In the approved launch scope, Makkah is an enabled destination for eligible requests with pickup in Riyadh. A Makkah transport plan depends on accurate address, access, timing, and building information as much as the items being moved. Naqlk collects those details in one request and has Sales review them before confirming whether the requested service and schedule are workable.','The flow supports eligible furniture and general-goods transport from Riyadh to Makkah. Packing and loading or unloading may be requested, subject to cargo, address, and availability review. A local journey with both endpoints inside Makkah is not in the currently published launch scope, and this page does not claim otherwise.','No Makkah address is assumed to be automatically reachable. Street, entrance, floor, and landmark notes help the team assess the location without publishing misleading blanket-coverage claims.','[{"question":"Can I request transport from Riyadh to Makkah?","answer":"Yes. You can submit an eligible request originating in Riyadh and going to Makkah. Confirmation depends on the cargo, addresses, date, and resources after review.","displayOrder":10},{"question":"Does the launch scope include local transport within Makkah?","answer":"No. The published local service currently applies when both endpoints are in Riyadh. Makkah is enabled as a destination for eligible requests originating in Riyadh.","displayOrder":20},{"question":"How do I receive a quotation for transport to Makkah?","answer":"Provide the Riyadh pickup, Makkah delivery address, item description, and preferred date. Sales reviews the details before issuing an itemized quotation.","displayOrder":30}]'::jsonb),
  ('MED','ar','خدمة نقل من الرياض إلى المدينة المنورة | نقلك','قدّم بيانات طلب النقل من الرياض إلى المدينة المنورة للأثاث أو البضائع العامة، واستلم عرضاً مفصلاً بعد التحقق من المسار والموارد.','طلب خدمة نقل مؤهلة من الرياض إلى المدينة المنورة','في النطاق التجاري المعتمد للإطلاق، تظهر المدينة المنورة كوجهة مفعلة للطلبات المؤهلة التي يبدأ استلامها من الرياض. تساعد نقلك سكان المدينة المنورة والمنشآت فيها على تحويل احتياج النقل إلى طلب منظم. يبدأ ذلك بوصف المنقولات والعنوانين وتوقيت الخدمة، مع إرفاق الصور عند فائدتها، حتى يستطيع الفريق فهم النطاق قبل تقديم أي التزام أو تسعير.','يدعم المسار نقل الأثاث والبضائع العامة المؤهلة من الرياض إلى المدينة المنورة. يمكن طلب التغليف أو التحميل والتنزيل، لكن تأكيدها يعتمد على مراجعة الحمولة والعنوانين والتوفر. النقل المحلي الذي يقع طرفاه داخل المدينة المنورة ليس ضمن نطاق الإطلاق المعلن حالياً، ولا تقدم الصفحة وعداً بخلاف ذلك.','تظل الخدمة مرتبطة بعنواني الطلب الفعليين ومتطلبات الدخول والتوقف. لا تعني إتاحة المدينة المنورة تشغيلياً أن جميع المواقع أو الأوقات مقبولة دون مراجعة.','[{"question":"هل يمكن طلب نقل من الرياض إلى المدينة المنورة؟","answer":"نعم، يمكن إرسال طلب مؤهل يبدأ من الرياض ويتجه إلى المدينة المنورة. يعتمد التأكيد على نوع المنقولات والعنوانين والموعد وتوفر الموارد بعد المراجعة.","displayOrder":10},{"question":"هل يتضمن نطاق الإطلاق النقل المحلي داخل المدينة المنورة؟","answer":"لا. النقل المحلي المعلن حالياً مخصص للطلبات التي يقع طرفاها في الرياض. تظهر المدينة المنورة كوجهة مفعلة للطلبات المؤهلة المنطلقة من الرياض.","displayOrder":20},{"question":"هل أحتاج إلى حساب لطلب النقل إلى المدينة المنورة؟","answer":"لا يلزم إنشاء حساب. يمكن إرسال الطلب المتجه إلى المدينة المنورة كزائر، ثم استخدام مرجع NQ ورقم الجوال في مسار التتبع المخصص.","displayOrder":30}]'::jsonb),
  ('MED','en','Transport Service from Riyadh to Madinah | Naqlk','Submit furniture or general-goods transport details from Riyadh to Madinah and receive an itemized quotation after route and resource review.','Request eligible transport from Riyadh to Madinah','In the approved launch scope, Madinah is an enabled destination for eligible requests with pickup in Riyadh. Naqlk helps households and businesses in Madinah turn a transport need into a structured request. Describing the items, both addresses, timing, and useful photos gives the team enough context to understand the scope before making a commitment or issuing a price.','The flow supports eligible furniture and general-goods transport from Riyadh to Madinah. Packing and loading or unloading may be requested, subject to cargo, address, and availability review. A local journey with both endpoints inside Madinah is not in the currently published launch scope, and this page does not claim otherwise.','Service depends on the actual pickup and delivery locations, entry conditions, and a practical vehicle stopping point. Operational availability in Madinah does not mean every site or time is accepted without review.','[{"question":"Can I request transport from Riyadh to Madinah?","answer":"Yes. You can submit an eligible request originating in Riyadh and going to Madinah. Confirmation depends on the cargo, addresses, date, and resources after review.","displayOrder":10},{"question":"Does the launch scope include local transport within Madinah?","answer":"No. The published local service currently applies when both endpoints are in Riyadh. Madinah is enabled as a destination for eligible requests originating in Riyadh.","displayOrder":20},{"question":"Do I need an account to request transport to Madinah?","answer":"No account is required. You can submit the Madinah request as a guest and use the NQ reference with the submitted mobile number in the dedicated tracking flow.","displayOrder":30}]'::jsonb),
  ('DMM','ar','طلبات النقل من الرياض إلى الدمام بخطوات واضحة | نقلك','رتّب طلباً متجهاً من الرياض إلى الدمام مع وصف الحمولة والعناوين وملاحظات الوصول، ثم راجع بنود عرض السعر قبل الاعتماد.','خدمات النقل المتجهة من الرياض إلى الدمام','في النطاق التجاري المعتمد للإطلاق، تظهر الدمام كوجهة مفعلة للطلبات المؤهلة التي يبدأ استلامها من الرياض. تخدم الدمام احتياجات منزلية وتجارية متنوعة، ولهذا تعتمد نقلك على تفاصيل الطلب بدلاً من افتراض نموذج واحد لكل عملية نقل. يوضح العميل نوع المنقولات والكميات التقريبية ونقاط الاستلام والتسليم، ثم تتم مراجعة الملاءمة والموعد قبل عرض السعر.','يدعم المسار نقل الأثاث والبضائع العامة المؤهلة من الرياض إلى الدمام. يمكن طلب التغليف أو التحميل والتنزيل، لكن تأكيدها يعتمد على مراجعة الحمولة والعنوانين والتوفر. النقل المحلي الذي يقع طرفاه داخل الدمام ليس ضمن نطاق الإطلاق المعلن حالياً، ولا تقدم الصفحة وعداً بخلاف ذلك.','تُراجع مواقع الدمام وفق بيانات الخريطة والعنوان المكتوب وملاحظات البوابة أو المصعد أو منطقة التوقف. لا تُعرض قائمة أحياء مصطنعة ولا وعد بتغطية شاملة.','[{"question":"هل يمكن طلب نقل من الرياض إلى الدمام؟","answer":"نعم، يمكن إرسال طلب مؤهل يبدأ من الرياض ويتجه إلى الدمام. يعتمد التأكيد على نوع المنقولات والعنوانين والموعد وتوفر الموارد بعد المراجعة.","displayOrder":10},{"question":"هل يتضمن نطاق الإطلاق النقل المحلي داخل الدمام؟","answer":"لا. النقل المحلي المعلن حالياً مخصص للطلبات التي يقع طرفاها في الرياض. تظهر الدمام كوجهة مفعلة للطلبات المؤهلة المنطلقة من الرياض.","displayOrder":20},{"question":"هل يمكن إضافة التغليف لطلب متجه إلى الدمام؟","answer":"يمكن اختيار التغليف عند تقديم الطلب المتجه إلى الدمام. يراجع الفريق عدد القطع وطبيعتها، ولا يُدرج الدعم إلا كبند واضح في عرض السعر المعتمد.","displayOrder":30}]'::jsonb),
  ('DMM','en','Structured Transport from Riyadh to Dammam | Naqlk','Arrange a Riyadh-to-Dammam request with cargo, address, and access notes, then review the quotation items before acceptance.','Transport services from Riyadh to Dammam','In the approved launch scope, Dammam is an enabled destination for eligible requests with pickup in Riyadh. Dammam includes varied household and commercial transport needs, so Naqlk assesses the actual request instead of assuming one model fits every move. Customers describe the items, approximate quantities, pickup point, and destination before suitability and timing are reviewed.','The flow supports eligible furniture and general-goods transport from Riyadh to Dammam. Packing and loading or unloading may be requested, subject to cargo, address, and availability review. A local journey with both endpoints inside Dammam is not in the currently published launch scope, and this page does not claim otherwise.','Dammam locations are reviewed using map coordinates, the written address, and notes about gates, lifts, or vehicle stopping space. No fabricated district list or blanket coverage promise is published.','[{"question":"Can I request transport from Riyadh to Dammam?","answer":"Yes. You can submit an eligible request originating in Riyadh and going to Dammam. Confirmation depends on the cargo, addresses, date, and resources after review.","displayOrder":10},{"question":"Does the launch scope include local transport within Dammam?","answer":"No. The published local service currently applies when both endpoints are in Riyadh. Dammam is enabled as a destination for eligible requests originating in Riyadh.","displayOrder":20},{"question":"Can packing be added to a request going to Dammam?","answer":"Packing can be selected for the Dammam request. The team reviews the items and includes support only as a clear line in the approved quotation.","displayOrder":30}]'::jsonb),
  ('KHO','ar','ترتيب نقل الأثاث والبضائع من الرياض إلى الخبر | نقلك','أرسل طلب نقل من الرياض إلى الخبر عبر مسار واضح يجمع المواقع والمنقولات والموعد، ويخضع لمراجعة الفريق قبل التنفيذ.','خطوات واضحة للنقل من الرياض إلى الخبر','في النطاق التجاري المعتمد للإطلاق، تظهر الخبر كوجهة مفعلة للطلبات المؤهلة التي يبدأ استلامها من الرياض. تبدأ عملية النقل الجيدة في الخبر بوصف واضح لما يجب نقله وكيفية الوصول إلى الموقعين. تجمع نقلك بيانات الأثاث أو البضائع والعناوين والتوقيت والملاحظات في طلب واحد، ليتحقق الفريق من النطاق قبل إعداد العرض وخطة التنفيذ.','يدعم المسار نقل الأثاث والبضائع العامة المؤهلة من الرياض إلى الخبر. يمكن طلب التغليف أو التحميل والتنزيل، لكن تأكيدها يعتمد على مراجعة الحمولة والعنوانين والتوفر. النقل المحلي الذي يقع طرفاه داخل الخبر ليس ضمن نطاق الإطلاق المعلن حالياً، ولا تقدم الصفحة وعداً بخلاف ذلك.','يُقيّم كل عنوان في الخبر على حدة، بما في ذلك مدخل المبنى ومساحة الحركة وموقع وقوف المركبة. لا تعتمد نقلك على تعميم واحد للمناطق السكنية والتجارية.','[{"question":"هل يمكن طلب نقل من الرياض إلى الخبر؟","answer":"نعم، يمكن إرسال طلب مؤهل يبدأ من الرياض ويتجه إلى الخبر. يعتمد التأكيد على نوع المنقولات والعنوانين والموعد وتوفر الموارد بعد المراجعة.","displayOrder":10},{"question":"هل يتضمن نطاق الإطلاق النقل المحلي داخل الخبر؟","answer":"لا. النقل المحلي المعلن حالياً مخصص للطلبات التي يقع طرفاها في الرياض. تظهر الخبر كوجهة مفعلة للطلبات المؤهلة المنطلقة من الرياض.","displayOrder":20},{"question":"كيف أحصل على عرض سعر لرحلة إلى الخبر؟","answer":"أدخل عنوان الاستلام في الرياض وعنوان التسليم في الخبر ووصف المنقولات والموعد. يراجع ممثل المبيعات البيانات قبل إرسال عرض مفصل.","displayOrder":30}]'::jsonb),
  ('KHO','en','Arrange Transport from Riyadh to Al Khobar | Naqlk','Send a transport request from Riyadh to Al Khobar through a clear flow covering locations, items, and timing before execution review.','A clear transport flow from Riyadh to Al Khobar','In the approved launch scope, Al Khobar is an enabled destination for eligible requests with pickup in Riyadh. A well-planned move in Al Khobar begins with a clear description of the items and access at both sites. Naqlk combines cargo, address, timing, and access notes in one request so the team can confirm the scope before preparing a quotation and execution plan.','The flow supports eligible furniture and general-goods transport from Riyadh to Al Khobar. Packing and loading or unloading may be requested, subject to cargo, address, and availability review. A local journey with both endpoints inside Al Khobar is not in the currently published launch scope, and this page does not claim otherwise.','Each Al Khobar address is assessed individually, including building entrance, movement space, and vehicle stopping conditions. Naqlk does not apply one blanket assumption to residential and commercial locations.','[{"question":"Can I request transport from Riyadh to Al Khobar?","answer":"Yes. You can submit an eligible request originating in Riyadh and going to Al Khobar. Confirmation depends on the cargo, addresses, date, and resources after review.","displayOrder":10},{"question":"Does the launch scope include local transport within Al Khobar?","answer":"No. The published local service currently applies when both endpoints are in Riyadh. Al Khobar is enabled as a destination for eligible requests originating in Riyadh.","displayOrder":20},{"question":"How do I receive a quotation for transport to Al Khobar?","answer":"Provide the Riyadh pickup, Al Khobar delivery address, item description, and preferred date. Sales reviews the details before issuing an itemized quotation.","displayOrder":30}]'::jsonb),
  ('DHA','ar','نقل الأثاث والبضائع من الرياض إلى الظهران | نقلك','اطلب نقل أثاث أو بضائع مؤهلة من الرياض إلى الظهران، مع مراجعة الحمولة والعنوانين والوصول قبل إرسال عرض سعر واضح من نقلك.','نقل الأثاث والبضائع من الرياض إلى الظهران','في النطاق التجاري المعتمد للإطلاق، تظهر الظهران كوجهة مفعلة للطلبات المؤهلة التي يبدأ استلامها من الرياض. تعتمد نقلك في الظهران على عنوان دقيق ووصف واقعي للمنقولات قبل اقتراح التنفيذ. يمكن للعميل توضيح نقطة الاستلام والوجهة والكميات التقريبية وأي قيود دخول، ما يساعد على تقليل الافتراضات عند مراجعة الطلب.','يدعم المسار نقل الأثاث والبضائع العامة المؤهلة من الرياض إلى الظهران. يمكن طلب التغليف أو التحميل والتنزيل، لكن تأكيدها يعتمد على مراجعة الحمولة والعنوانين والتوفر. النقل المحلي الذي يقع طرفاه داخل الظهران ليس ضمن نطاق الإطلاق المعلن حالياً، ولا تقدم الصفحة وعداً بخلاف ذلك.','تُقبل الطلبات في الظهران بحسب صلاحية العنوان والوصول والتوقيت وتوفر الموارد. إدراج إحداثيات الموقع ووصف البوابة يساعد أكثر من الاعتماد على اسم المنطقة وحده.','[{"question":"هل يمكن طلب نقل من الرياض إلى الظهران؟","answer":"نعم، يمكن إرسال طلب مؤهل يبدأ من الرياض ويتجه إلى الظهران. يعتمد التأكيد على نوع المنقولات والعنوانين والموعد وتوفر الموارد بعد المراجعة.","displayOrder":10},{"question":"هل يتضمن نطاق الإطلاق النقل المحلي داخل الظهران؟","answer":"لا. النقل المحلي المعلن حالياً مخصص للطلبات التي يقع طرفاها في الرياض. تظهر الظهران كوجهة مفعلة للطلبات المؤهلة المنطلقة من الرياض.","displayOrder":20},{"question":"هل أحتاج إلى حساب لطلب النقل إلى الظهران؟","answer":"لا يلزم إنشاء حساب. يمكن إرسال الطلب المتجه إلى الظهران كزائر، ثم استخدام مرجع NQ ورقم الجوال في مسار التتبع المخصص.","displayOrder":30}]'::jsonb),
  ('DHA','en','Furniture and Goods Transport from Riyadh to Dhahran | Naqlk','Request eligible furniture or goods transport from Riyadh to Dhahran, with cargo, addresses, and access reviewed before Naqlk issues a clear quotation.','Furniture and goods transport from Riyadh to Dhahran','In the approved launch scope, Dhahran is an enabled destination for eligible requests with pickup in Riyadh. Naqlk relies on an accurate Dhahran address and a realistic item description before proposing execution. Customers can identify the pickup point, destination, approximate quantities, and any entry restrictions, reducing assumptions during the request review.','The flow supports eligible furniture and general-goods transport from Riyadh to Dhahran. Packing and loading or unloading may be requested, subject to cargo, address, and availability review. A local journey with both endpoints inside Dhahran is not in the currently published launch scope, and this page does not claim otherwise.','Dhahran requests are accepted according to address suitability, access, timing, and available resources. Map coordinates and gate notes are more useful than relying on the area name alone.','[{"question":"Can I request transport from Riyadh to Dhahran?","answer":"Yes. You can submit an eligible request originating in Riyadh and going to Dhahran. Confirmation depends on the cargo, addresses, date, and resources after review.","displayOrder":10},{"question":"Does the launch scope include local transport within Dhahran?","answer":"No. The published local service currently applies when both endpoints are in Riyadh. Dhahran is enabled as a destination for eligible requests originating in Riyadh.","displayOrder":20},{"question":"Do I need an account to request transport to Dhahran?","answer":"No account is required. You can submit the Dhahran request as a guest and use the NQ reference with the submitted mobile number in the dedicated tracking flow.","displayOrder":30}]'::jsonb),
  ('AHS','ar','خدمة نقل مدروسة من الرياض إلى الأحساء | نقلك','نظّم رحلة نقل مؤهلة من الرياض إلى الأحساء عبر نقلك، وأضف تفاصيل المنقولات والخدمات الاختيارية ليُراجع الفريق الطلب قبل التسعير.','تنظيم رحلة النقل من الرياض إلى الأحساء','في النطاق التجاري المعتمد للإطلاق، تظهر الأحساء كوجهة مفعلة للطلبات المؤهلة التي يبدأ استلامها من الرياض. اتساع النطاق العمراني في الأحساء يجعل تحديد نقطة الاستلام والتسليم بدقة خطوة مهمة. يتيح طلب نقلك إضافة الإحداثيات والعنوان الوصفي وتفاصيل الحمولة، حتى يراجع الفريق المسافة والوصول ومتطلبات الخدمة قبل التأكيد.','يدعم المسار نقل الأثاث والبضائع العامة المؤهلة من الرياض إلى الأحساء. يمكن طلب التغليف أو التحميل والتنزيل، لكن تأكيدها يعتمد على مراجعة الحمولة والعنوانين والتوفر. النقل المحلي الذي يقع طرفاه داخل الأحساء ليس ضمن نطاق الإطلاق المعلن حالياً، ولا تقدم الصفحة وعداً بخلاف ذلك.','لا تستخدم الصفحة أسماء مناطق فرعية غير موثقة لإيحاء بتغطية أوسع. تُراجع كل نقطة في الأحساء باستخدام بيانات العنوان التي يرسلها العميل ونطاق التشغيل الحالي.','[{"question":"هل يمكن طلب نقل من الرياض إلى الأحساء؟","answer":"نعم، يمكن إرسال طلب مؤهل يبدأ من الرياض ويتجه إلى الأحساء. يعتمد التأكيد على نوع المنقولات والعنوانين والموعد وتوفر الموارد بعد المراجعة.","displayOrder":10},{"question":"هل يتضمن نطاق الإطلاق النقل المحلي داخل الأحساء؟","answer":"لا. النقل المحلي المعلن حالياً مخصص للطلبات التي يقع طرفاها في الرياض. تظهر الأحساء كوجهة مفعلة للطلبات المؤهلة المنطلقة من الرياض.","displayOrder":20},{"question":"هل يمكن إضافة التغليف لطلب متجه إلى الأحساء؟","answer":"يمكن اختيار التغليف عند تقديم الطلب المتجه إلى الأحساء. يراجع الفريق عدد القطع وطبيعتها، ولا يُدرج الدعم إلا كبند واضح في عرض السعر المعتمد.","displayOrder":30}]'::jsonb),
  ('AHS','en','Reviewed Transport from Riyadh to Al Ahsa | Naqlk','Organize an eligible Riyadh-to-Al Ahsa journey, adding item and optional-service details for team review before pricing.','Plan a transport journey from Riyadh to Al Ahsa','In the approved launch scope, Al Ahsa is an enabled destination for eligible requests with pickup in Riyadh. Al Ahsa''s broad urban area makes precise pickup and delivery points especially useful. A Naqlk request can include coordinates, a written address, and cargo details so the team can assess distance, access, and service requirements before confirmation.','The flow supports eligible furniture and general-goods transport from Riyadh to Al Ahsa. Packing and loading or unloading may be requested, subject to cargo, address, and availability review. A local journey with both endpoints inside Al Ahsa is not in the currently published launch scope, and this page does not claim otherwise.','The page does not use unverified sub-area lists to imply wider coverage. Each Al Ahsa point is reviewed using customer-provided address data and the current operating scope.','[{"question":"Can I request transport from Riyadh to Al Ahsa?","answer":"Yes. You can submit an eligible request originating in Riyadh and going to Al Ahsa. Confirmation depends on the cargo, addresses, date, and resources after review.","displayOrder":10},{"question":"Does the launch scope include local transport within Al Ahsa?","answer":"No. The published local service currently applies when both endpoints are in Riyadh. Al Ahsa is enabled as a destination for eligible requests originating in Riyadh.","displayOrder":20},{"question":"Can packing be added to a request going to Al Ahsa?","answer":"Packing can be selected for the Al Ahsa request. The team reviews the items and includes support only as a clear line in the approved quotation.","displayOrder":30}]'::jsonb),
  ('JUB','ar','نقل الأثاث والبضائع العامة من الرياض إلى الجبيل | نقلك','قدّم بيانات طلب النقل من الرياض إلى الجبيل للأثاث أو البضائع العامة، واستلم عرضاً مفصلاً بعد التحقق من المسار والموارد.','طلب خدمة نقل مؤهلة من الرياض إلى الجبيل','في النطاق التجاري المعتمد للإطلاق، تظهر الجبيل كوجهة مفعلة للطلبات المؤهلة التي يبدأ استلامها من الرياض. تتعامل نقلك في الجبيل مع احتياجات نقل الأثاث والبضائع العامة المؤهلة، مع فصل واضح بينها وبين النقل الصناعي المتخصص غير المشمول. يصف العميل الحمولة والاستخدام المطلوب والعنوانين، ثم يراجع الفريق ملاءمة الخدمة قبل التسعير.','يدعم المسار نقل الأثاث والبضائع العامة المؤهلة من الرياض إلى الجبيل. يمكن طلب التغليف أو التحميل والتنزيل، لكن تأكيدها يعتمد على مراجعة الحمولة والعنوانين والتوفر. النقل المحلي الذي يقع طرفاه داخل الجبيل ليس ضمن نطاق الإطلاق المعلن حالياً، ولا تقدم الصفحة وعداً بخلاف ذلك.','ترتبط إمكانية التنفيذ بالمواقع الفعلية ونوع المنقولات وشروط الدخول. لا تُعد الإتاحة التشغيلية في الجبيل موافقة مسبقة على المواقع الصناعية أو المقيدة.','[{"question":"هل يمكن طلب نقل من الرياض إلى الجبيل؟","answer":"نعم، يمكن إرسال طلب مؤهل يبدأ من الرياض ويتجه إلى الجبيل. يعتمد التأكيد على نوع المنقولات والعنوانين والموعد وتوفر الموارد بعد المراجعة.","displayOrder":10},{"question":"هل يتضمن نطاق الإطلاق النقل المحلي داخل الجبيل؟","answer":"لا. النقل المحلي المعلن حالياً مخصص للطلبات التي يقع طرفاها في الرياض. تظهر الجبيل كوجهة مفعلة للطلبات المؤهلة المنطلقة من الرياض.","displayOrder":20},{"question":"كيف أحصل على عرض سعر لرحلة إلى الجبيل؟","answer":"أدخل عنوان الاستلام في الرياض وعنوان التسليم في الجبيل ووصف المنقولات والموعد. يراجع ممثل المبيعات البيانات قبل إرسال عرض مفصل.","displayOrder":30}]'::jsonb),
  ('JUB','en','General Goods and Furniture from Riyadh to Jubail | Naqlk','Submit furniture or general-goods transport details from Riyadh to Jubail and receive an itemized quotation after route and resource review.','Request eligible transport from Riyadh to Jubail','In the approved launch scope, Jubail is an enabled destination for eligible requests with pickup in Riyadh. Naqlk serves eligible furniture and general-goods needs in Jubail while keeping them distinct from unsupported specialist industrial haulage. Customers describe the load, intended service, and both addresses before the team reviews suitability and prepares pricing.','The flow supports eligible furniture and general-goods transport from Riyadh to Jubail. Packing and loading or unloading may be requested, subject to cargo, address, and availability review. A local journey with both endpoints inside Jubail is not in the currently published launch scope, and this page does not claim otherwise.','Execution depends on the actual sites, cargo type, and entry conditions. Jubail''s operational status is not advance approval for industrial or otherwise restricted locations.','[{"question":"Can I request transport from Riyadh to Jubail?","answer":"Yes. You can submit an eligible request originating in Riyadh and going to Jubail. Confirmation depends on the cargo, addresses, date, and resources after review.","displayOrder":10},{"question":"Does the launch scope include local transport within Jubail?","answer":"No. The published local service currently applies when both endpoints are in Riyadh. Jubail is enabled as a destination for eligible requests originating in Riyadh.","displayOrder":20},{"question":"How do I receive a quotation for transport to Jubail?","answer":"Provide the Riyadh pickup, Jubail delivery address, item description, and preferred date. Sales reviews the details before issuing an itemized quotation.","displayOrder":30}]'::jsonb),
  ('TAI','ar','تنظيم رحلة نقل من الرياض إلى الطائف | نقلك','رتّب طلباً متجهاً من الرياض إلى الطائف مع وصف الحمولة والعناوين وملاحظات الوصول، ثم راجع بنود عرض السعر قبل الاعتماد.','خدمات النقل المتجهة من الرياض إلى الطائف','في النطاق التجاري المعتمد للإطلاق، تظهر الطائف كوجهة مفعلة للطلبات المؤهلة التي يبدأ استلامها من الرياض. يساعد وصف الموقع وطبيعة الوصول في الطائف على بناء خطة نقل أكثر دقة، خصوصاً عندما تختلف مداخل المباني أو ظروف الطريق. تجمع نقلك هذه الملاحظات مع بيانات المنقولات والموعد، ثم تراجع الطلب قبل اقتراح التنفيذ.','يدعم المسار نقل الأثاث والبضائع العامة المؤهلة من الرياض إلى الطائف. يمكن طلب التغليف أو التحميل والتنزيل، لكن تأكيدها يعتمد على مراجعة الحمولة والعنوانين والتوفر. النقل المحلي الذي يقع طرفاه داخل الطائف ليس ضمن نطاق الإطلاق المعلن حالياً، ولا تقدم الصفحة وعداً بخلاف ذلك.','تُراجع نقاط الطائف حسب الإحداثيات والعنوان والوصول الفعلي، بما في ذلك أي ملاحظة طريق يقدمها العميل. لا تقدم الصفحة ضماناً عاماً لكل موقع أو موعد.','[{"question":"هل يمكن طلب نقل من الرياض إلى الطائف؟","answer":"نعم، يمكن إرسال طلب مؤهل يبدأ من الرياض ويتجه إلى الطائف. يعتمد التأكيد على نوع المنقولات والعنوانين والموعد وتوفر الموارد بعد المراجعة.","displayOrder":10},{"question":"هل يتضمن نطاق الإطلاق النقل المحلي داخل الطائف؟","answer":"لا. النقل المحلي المعلن حالياً مخصص للطلبات التي يقع طرفاها في الرياض. تظهر الطائف كوجهة مفعلة للطلبات المؤهلة المنطلقة من الرياض.","displayOrder":20},{"question":"هل أحتاج إلى حساب لطلب النقل إلى الطائف؟","answer":"لا يلزم إنشاء حساب. يمكن إرسال الطلب المتجه إلى الطائف كزائر، ثم استخدام مرجع NQ ورقم الجوال في مسار التتبع المخصص.","displayOrder":30}]'::jsonb),
  ('TAI','en','Plan a Transport Journey from Riyadh to Taif | Naqlk','Arrange a Riyadh-to-Taif request with cargo, address, and access notes, then review the quotation items before acceptance.','Transport services from Riyadh to Taif','In the approved launch scope, Taif is an enabled destination for eligible requests with pickup in Riyadh. Location and access information helps create a more accurate Taif transport plan, particularly where building entrances or road conditions differ. Naqlk combines those notes with item and timing details, then reviews the request before proposing execution.','The flow supports eligible furniture and general-goods transport from Riyadh to Taif. Packing and loading or unloading may be requested, subject to cargo, address, and availability review. A local journey with both endpoints inside Taif is not in the currently published launch scope, and this page does not claim otherwise.','Taif points are assessed using coordinates, the written address, and any road-access note supplied by the customer. The page does not guarantee every location or time in advance.','[{"question":"Can I request transport from Riyadh to Taif?","answer":"Yes. You can submit an eligible request originating in Riyadh and going to Taif. Confirmation depends on the cargo, addresses, date, and resources after review.","displayOrder":10},{"question":"Does the launch scope include local transport within Taif?","answer":"No. The published local service currently applies when both endpoints are in Riyadh. Taif is enabled as a destination for eligible requests originating in Riyadh.","displayOrder":20},{"question":"Do I need an account to request transport to Taif?","answer":"No account is required. You can submit the Taif request as a guest and use the NQ reference with the submitted mobile number in the dedicated tracking flow.","displayOrder":30}]'::jsonb),
  ('TUU','ar','طلب نقل أثاث وبضائع من الرياض إلى تبوك | نقلك','أرسل طلب نقل من الرياض إلى تبوك عبر مسار واضح يجمع المواقع والمنقولات والموعد، ويخضع لمراجعة الفريق قبل التنفيذ.','خطوات واضحة للنقل من الرياض إلى تبوك','في النطاق التجاري المعتمد للإطلاق، تظهر تبوك كوجهة مفعلة للطلبات المؤهلة التي يبدأ استلامها من الرياض. تظهر تبوك في نطاق الإطلاق كوجهة للطلبات المؤهلة التي تبدأ من الرياض. يجمع نموذج نقلك نوع الخدمة والحمولة وعنوان الاستلام في الرياض وعنوان التسليم في تبوك والتاريخ المرغوب، حتى يقيّم الفريق المسافة والوصول والموارد دون افتراض جدول ثابت.','يدعم المسار نقل الأثاث والبضائع العامة المؤهلة من الرياض إلى تبوك. يمكن طلب التغليف أو التحميل والتنزيل، لكن تأكيدها يعتمد على مراجعة الحمولة والعنوانين والتوفر. النقل المحلي الذي يقع طرفاه داخل تبوك ليس ضمن نطاق الإطلاق المعلن حالياً، ولا تقدم الصفحة وعداً بخلاف ذلك.','يعتمد نطاق تبوك الفعلي على نقطة الاستلام والتسليم وملاءمة الوصول والموعد. لا تعني صفحة المدينة وجود جدول ثابت لكل وجهة أو تغطية غير محدودة.','[{"question":"هل يمكن طلب نقل من الرياض إلى تبوك؟","answer":"نعم، يمكن إرسال طلب مؤهل يبدأ من الرياض ويتجه إلى تبوك. يعتمد التأكيد على نوع المنقولات والعنوانين والموعد وتوفر الموارد بعد المراجعة.","displayOrder":10},{"question":"هل يتضمن نطاق الإطلاق النقل المحلي داخل تبوك؟","answer":"لا. النقل المحلي المعلن حالياً مخصص للطلبات التي يقع طرفاها في الرياض. تظهر تبوك كوجهة مفعلة للطلبات المؤهلة المنطلقة من الرياض.","displayOrder":20},{"question":"هل يمكن إضافة التغليف لطلب متجه إلى تبوك؟","answer":"يمكن اختيار التغليف عند تقديم الطلب المتجه إلى تبوك. يراجع الفريق عدد القطع وطبيعتها، ولا يُدرج الدعم إلا كبند واضح في عرض السعر المعتمد.","displayOrder":30}]'::jsonb),
  ('TUU','en','Furniture and Goods Transport from Riyadh to Tabuk | Naqlk','Send a transport request from Riyadh to Tabuk through a clear flow covering locations, items, and timing before execution review.','A clear transport flow from Riyadh to Tabuk','In the approved launch scope, Tabuk is an enabled destination for eligible requests with pickup in Riyadh. Tabuk appears in the launch scope as a destination for eligible requests originating in Riyadh. The Naqlk form captures service type, cargo, the Riyadh pickup, the Tabuk delivery point, and preferred date so the team can assess distance, access, and resources without assuming a fixed schedule.','The flow supports eligible furniture and general-goods transport from Riyadh to Tabuk. Packing and loading or unloading may be requested, subject to cargo, address, and availability review. A local journey with both endpoints inside Tabuk is not in the currently published launch scope, and this page does not claim otherwise.','The practical Tabuk scope depends on pickup, delivery, access suitability, and timing. A city page does not imply a fixed schedule to every destination or unlimited coverage.','[{"question":"Can I request transport from Riyadh to Tabuk?","answer":"Yes. You can submit an eligible request originating in Riyadh and going to Tabuk. Confirmation depends on the cargo, addresses, date, and resources after review.","displayOrder":10},{"question":"Does the launch scope include local transport within Tabuk?","answer":"No. The published local service currently applies when both endpoints are in Riyadh. Tabuk is enabled as a destination for eligible requests originating in Riyadh.","displayOrder":20},{"question":"Can packing be added to a request going to Tabuk?","answer":"Packing can be selected for the Tabuk request. The team reviews the items and includes support only as a clear line in the approved quotation.","displayOrder":30}]'::jsonb),
  ('AHB','ar','خدمة نقل تراعي الوصول من الرياض إلى أبها | نقلك','اطلب نقل أثاث أو بضائع مؤهلة من الرياض إلى أبها، مع مراجعة الحمولة والعنوانين والوصول قبل إرسال عرض سعر واضح من نقلك.','نقل الأثاث والبضائع من الرياض إلى أبها','في النطاق التجاري المعتمد للإطلاق، تظهر أبها كوجهة مفعلة للطلبات المؤهلة التي يبدأ استلامها من الرياض. تجعل طبيعة أبها المرتفعة وتنوع الوصول بين المواقع من تفاصيل الطريق والمدخل جزءاً مهماً من طلب النقل. تتيح نقلك إضافة الإحداثيات ووصف المبنى والقطع المراد نقلها حتى تتم مراجعة الحالة الفعلية بدلاً من الاعتماد على اسم المدينة فقط.','يدعم المسار نقل الأثاث والبضائع العامة المؤهلة من الرياض إلى أبها. يمكن طلب التغليف أو التحميل والتنزيل، لكن تأكيدها يعتمد على مراجعة الحمولة والعنوانين والتوفر. النقل المحلي الذي يقع طرفاه داخل أبها ليس ضمن نطاق الإطلاق المعلن حالياً، ولا تقدم الصفحة وعداً بخلاف ذلك.','لا تدعي نقلك الوصول التلقائي إلى كل موقع في أبها. تُراجع العناوين وملاحظات الطريق والتوقف لكل طلب، وقد يتطلب الفريق معلومات إضافية قبل التأكيد.','[{"question":"هل يمكن طلب نقل من الرياض إلى أبها؟","answer":"نعم، يمكن إرسال طلب مؤهل يبدأ من الرياض ويتجه إلى أبها. يعتمد التأكيد على نوع المنقولات والعنوانين والموعد وتوفر الموارد بعد المراجعة.","displayOrder":10},{"question":"هل يتضمن نطاق الإطلاق النقل المحلي داخل أبها؟","answer":"لا. النقل المحلي المعلن حالياً مخصص للطلبات التي يقع طرفاها في الرياض. تظهر أبها كوجهة مفعلة للطلبات المؤهلة المنطلقة من الرياض.","displayOrder":20},{"question":"كيف أحصل على عرض سعر لرحلة إلى أبها؟","answer":"أدخل عنوان الاستلام في الرياض وعنوان التسليم في أبها ووصف المنقولات والموعد. يراجع ممثل المبيعات البيانات قبل إرسال عرض مفصل.","displayOrder":30}]'::jsonb),
  ('AHB','en','Access-Aware Transport from Riyadh to Abha | Naqlk','Request eligible furniture or goods transport from Riyadh to Abha, with cargo, addresses, and access reviewed before Naqlk issues a clear quotation.','Furniture and goods transport from Riyadh to Abha','In the approved launch scope, Abha is an enabled destination for eligible requests with pickup in Riyadh. Abha''s elevated setting and varied site access make road and entrance details an important part of a transport request. Naqlk lets customers add coordinates, building notes, and item information so the real location is reviewed rather than relying on the city name alone.','The flow supports eligible furniture and general-goods transport from Riyadh to Abha. Packing and loading or unloading may be requested, subject to cargo, address, and availability review. A local journey with both endpoints inside Abha is not in the currently published launch scope, and this page does not claim otherwise.','Naqlk does not claim automatic access to every Abha location. Addresses, road notes, and stopping conditions are reviewed for each request, and the team may ask for additional information.','[{"question":"Can I request transport from Riyadh to Abha?","answer":"Yes. You can submit an eligible request originating in Riyadh and going to Abha. Confirmation depends on the cargo, addresses, date, and resources after review.","displayOrder":10},{"question":"Does the launch scope include local transport within Abha?","answer":"No. The published local service currently applies when both endpoints are in Riyadh. Abha is enabled as a destination for eligible requests originating in Riyadh.","displayOrder":20},{"question":"How do I receive a quotation for transport to Abha?","answer":"Provide the Riyadh pickup, Abha delivery address, item description, and preferred date. Sales reviews the details before issuing an itemized quotation.","displayOrder":30}]'::jsonb),
  ('KMX','ar','نقل الأثاث والبضائع من الرياض إلى خميس مشيط | نقلك','نظّم رحلة نقل مؤهلة من الرياض إلى خميس مشيط عبر نقلك، وأضف تفاصيل المنقولات والخدمات الاختيارية ليُراجع الفريق الطلب قبل التسعير.','تنظيم رحلة النقل من الرياض إلى خميس مشيط','في النطاق التجاري المعتمد للإطلاق، تظهر خميس مشيط كوجهة مفعلة للطلبات المؤهلة التي يبدأ استلامها من الرياض. يمنح طلب نقلك في خميس مشيط الفريق صورة عملية عن النقل المطلوب قبل تحديد الحل. يضيف العميل نوع الخدمة وموقعي الاستلام والتسليم ووصف المنقولات والموعد، مع ملاحظات الوصول التي قد تؤثر في الوقوف أو حركة القطع.','يدعم المسار نقل الأثاث والبضائع العامة المؤهلة من الرياض إلى خميس مشيط. يمكن طلب التغليف أو التحميل والتنزيل، لكن تأكيدها يعتمد على مراجعة الحمولة والعنوانين والتوفر. النقل المحلي الذي يقع طرفاه داخل خميس مشيط ليس ضمن نطاق الإطلاق المعلن حالياً، ولا تقدم الصفحة وعداً بخلاف ذلك.','تُحدد قابلية الخدمة في خميس مشيط من واقع العنوانين ونطاق التشغيل وتوفر الموارد. لا تنشر الصفحة قائمة أحياء غير موثقة أو وعداً مسبقاً لكل طلب.','[{"question":"هل يمكن طلب نقل من الرياض إلى خميس مشيط؟","answer":"نعم، يمكن إرسال طلب مؤهل يبدأ من الرياض ويتجه إلى خميس مشيط. يعتمد التأكيد على نوع المنقولات والعنوانين والموعد وتوفر الموارد بعد المراجعة.","displayOrder":10},{"question":"هل يتضمن نطاق الإطلاق النقل المحلي داخل خميس مشيط؟","answer":"لا. النقل المحلي المعلن حالياً مخصص للطلبات التي يقع طرفاها في الرياض. تظهر خميس مشيط كوجهة مفعلة للطلبات المؤهلة المنطلقة من الرياض.","displayOrder":20},{"question":"هل أحتاج إلى حساب لطلب النقل إلى خميس مشيط؟","answer":"لا يلزم إنشاء حساب. يمكن إرسال الطلب المتجه إلى خميس مشيط كزائر، ثم استخدام مرجع NQ ورقم الجوال في مسار التتبع المخصص.","displayOrder":30}]'::jsonb),
  ('KMX','en','Transport from Riyadh to Khamis Mushait | Naqlk','Organize an eligible Riyadh-to-Khamis Mushait journey, adding item and optional-service details for team review before pricing.','Plan a transport journey from Riyadh to Khamis Mushait','In the approved launch scope, Khamis Mushait is an enabled destination for eligible requests with pickup in Riyadh. A Naqlk request in Khamis Mushait gives the team a practical view of the needed transport before a solution is selected. Customers add service type, pickup and delivery locations, item details, timing, and access notes that may affect parking or item movement.','The flow supports eligible furniture and general-goods transport from Riyadh to Khamis Mushait. Packing and loading or unloading may be requested, subject to cargo, address, and availability review. A local journey with both endpoints inside Khamis Mushait is not in the currently published launch scope, and this page does not claim otherwise.','Service feasibility in Khamis Mushait is based on the addresses, current operating scope, and resource availability. No unverified district list or advance acceptance promise is published.','[{"question":"Can I request transport from Riyadh to Khamis Mushait?","answer":"Yes. You can submit an eligible request originating in Riyadh and going to Khamis Mushait. Confirmation depends on the cargo, addresses, date, and resources after review.","displayOrder":10},{"question":"Does the launch scope include local transport within Khamis Mushait?","answer":"No. The published local service currently applies when both endpoints are in Riyadh. Khamis Mushait is enabled as a destination for eligible requests originating in Riyadh.","displayOrder":20},{"question":"Do I need an account to request transport to Khamis Mushait?","answer":"No account is required. You can submit the Khamis Mushait request as a guest and use the NQ reference with the submitted mobile number in the dedicated tracking flow.","displayOrder":30}]'::jsonb),
  ('ELQ','ar','ترتيب طلب نقل من الرياض إلى بريدة | نقلك','قدّم بيانات طلب النقل من الرياض إلى بريدة للأثاث أو البضائع العامة، واستلم عرضاً مفصلاً بعد التحقق من المسار والموارد.','طلب خدمة نقل مؤهلة من الرياض إلى بريدة','في النطاق التجاري المعتمد للإطلاق، تظهر بريدة كوجهة مفعلة للطلبات المؤهلة التي يبدأ استلامها من الرياض. تساعد نقلك العملاء في بريدة على وصف احتياج النقل بطريقة تقلل الغموض عند التسعير. تشمل البيانات العناوين ونوع القطع والكميات التقريبية والتاريخ، ويمكن إضافة صور أو ملاحظات للمداخل عندما تسهم في تقييم الطلب.','يدعم المسار نقل الأثاث والبضائع العامة المؤهلة من الرياض إلى بريدة. يمكن طلب التغليف أو التحميل والتنزيل، لكن تأكيدها يعتمد على مراجعة الحمولة والعنوانين والتوفر. النقل المحلي الذي يقع طرفاه داخل بريدة ليس ضمن نطاق الإطلاق المعلن حالياً، ولا تقدم الصفحة وعداً بخلاف ذلك.','تُراجع نقاط بريدة بشكل مستقل وفق دقة الموقع وإمكانية الوصول والموارد المتوفرة في التاريخ المطلوب. لا تُفهم الإتاحة كضمان لكل حي أو مبنى.','[{"question":"هل يمكن طلب نقل من الرياض إلى بريدة؟","answer":"نعم، يمكن إرسال طلب مؤهل يبدأ من الرياض ويتجه إلى بريدة. يعتمد التأكيد على نوع المنقولات والعنوانين والموعد وتوفر الموارد بعد المراجعة.","displayOrder":10},{"question":"هل يتضمن نطاق الإطلاق النقل المحلي داخل بريدة؟","answer":"لا. النقل المحلي المعلن حالياً مخصص للطلبات التي يقع طرفاها في الرياض. تظهر بريدة كوجهة مفعلة للطلبات المؤهلة المنطلقة من الرياض.","displayOrder":20},{"question":"هل يمكن إضافة التغليف لطلب متجه إلى بريدة؟","answer":"يمكن اختيار التغليف عند تقديم الطلب المتجه إلى بريدة. يراجع الفريق عدد القطع وطبيعتها، ولا يُدرج الدعم إلا كبند واضح في عرض السعر المعتمد.","displayOrder":30}]'::jsonb),
  ('ELQ','en','Arrange a Transport Request from Riyadh to Buraidah | Naqlk','Submit furniture or general-goods transport details from Riyadh to Buraidah and receive an itemized quotation after route and resource review.','Request eligible transport from Riyadh to Buraidah','In the approved launch scope, Buraidah is an enabled destination for eligible requests with pickup in Riyadh. Naqlk helps Buraidah customers describe a transport need in a way that reduces uncertainty during pricing. Addresses, item types, approximate quantities, and date are captured, with photos or entrance notes added when they improve the assessment.','The flow supports eligible furniture and general-goods transport from Riyadh to Buraidah. Packing and loading or unloading may be requested, subject to cargo, address, and availability review. A local journey with both endpoints inside Buraidah is not in the currently published launch scope, and this page does not claim otherwise.','Buraidah points are reviewed independently using location accuracy, access feasibility, and resources available for the requested date. Operational availability is not a guarantee for every district or building.','[{"question":"Can I request transport from Riyadh to Buraidah?","answer":"Yes. You can submit an eligible request originating in Riyadh and going to Buraidah. Confirmation depends on the cargo, addresses, date, and resources after review.","displayOrder":10},{"question":"Does the launch scope include local transport within Buraidah?","answer":"No. The published local service currently applies when both endpoints are in Riyadh. Buraidah is enabled as a destination for eligible requests originating in Riyadh.","displayOrder":20},{"question":"Can packing be added to a request going to Buraidah?","answer":"Packing can be selected for the Buraidah request. The team reviews the items and includes support only as a clear line in the approved quotation.","displayOrder":30}]'::jsonb),
  ('HAS','ar','خدمة نقل قابلة للتخطيط من الرياض إلى حائل | نقلك','رتّب طلباً متجهاً من الرياض إلى حائل مع وصف الحمولة والعناوين وملاحظات الوصول، ثم راجع بنود عرض السعر قبل الاعتماد.','خدمات النقل المتجهة من الرياض إلى حائل','في النطاق التجاري المعتمد للإطلاق، تظهر حائل كوجهة مفعلة للطلبات المؤهلة التي يبدأ استلامها من الرياض. توفر نقلك في حائل نموذجاً يجمع ما يحتاجه الفريق لتقييم عملية النقل دون اتصالات متفرقة. يوضح العميل الخدمة المطلوبة وموقعي الرحلة والمنقولات والتوقيت، ثم تتم مراجعة المعلومات لإعداد نطاق مفهوم وعرض سعر قابل للمراجعة.','يدعم المسار نقل الأثاث والبضائع العامة المؤهلة من الرياض إلى حائل. يمكن طلب التغليف أو التحميل والتنزيل، لكن تأكيدها يعتمد على مراجعة الحمولة والعنوانين والتوفر. النقل المحلي الذي يقع طرفاه داخل حائل ليس ضمن نطاق الإطلاق المعلن حالياً، ولا تقدم الصفحة وعداً بخلاف ذلك.','يُحدد نطاق العمل من العناوين الفعلية والوصول والجدول المتاح، لا من اسم حائل وحده. لا يوجد في الصفحة ادعاء بجدول رحلات ثابت أو تغطية كل موقع.','[{"question":"هل يمكن طلب نقل من الرياض إلى حائل؟","answer":"نعم، يمكن إرسال طلب مؤهل يبدأ من الرياض ويتجه إلى حائل. يعتمد التأكيد على نوع المنقولات والعنوانين والموعد وتوفر الموارد بعد المراجعة.","displayOrder":10},{"question":"هل يتضمن نطاق الإطلاق النقل المحلي داخل حائل؟","answer":"لا. النقل المحلي المعلن حالياً مخصص للطلبات التي يقع طرفاها في الرياض. تظهر حائل كوجهة مفعلة للطلبات المؤهلة المنطلقة من الرياض.","displayOrder":20},{"question":"كيف أحصل على عرض سعر لرحلة إلى حائل؟","answer":"أدخل عنوان الاستلام في الرياض وعنوان التسليم في حائل ووصف المنقولات والموعد. يراجع ممثل المبيعات البيانات قبل إرسال عرض مفصل.","displayOrder":30}]'::jsonb),
  ('HAS','en','Planned Transport from Riyadh to Hail | Naqlk','Arrange a Riyadh-to-Hail request with cargo, address, and access notes, then review the quotation items before acceptance.','Transport services from Riyadh to Hail','In the approved launch scope, Hail is an enabled destination for eligible requests with pickup in Riyadh. Naqlk provides a Hail request form that gathers what the team needs to assess a move without fragmented conversations. Customers identify the service, journey points, items, and timing before the information is reviewed into a clear scope and quotation.','The flow supports eligible furniture and general-goods transport from Riyadh to Hail. Packing and loading or unloading may be requested, subject to cargo, address, and availability review. A local journey with both endpoints inside Hail is not in the currently published launch scope, and this page does not claim otherwise.','The working scope comes from actual addresses, access, and an available schedule rather than the Hail name alone. This page does not claim fixed departures or coverage of every location.','[{"question":"Can I request transport from Riyadh to Hail?","answer":"Yes. You can submit an eligible request originating in Riyadh and going to Hail. Confirmation depends on the cargo, addresses, date, and resources after review.","displayOrder":10},{"question":"Does the launch scope include local transport within Hail?","answer":"No. The published local service currently applies when both endpoints are in Riyadh. Hail is enabled as a destination for eligible requests originating in Riyadh.","displayOrder":20},{"question":"How do I receive a quotation for transport to Hail?","answer":"Provide the Riyadh pickup, Hail delivery address, item description, and preferred date. Sales reviews the details before issuing an itemized quotation.","displayOrder":30}]'::jsonb),
  ('YNB','ar','نقل الأثاث والبضائع العامة من الرياض إلى ينبع | نقلك','أرسل طلب نقل من الرياض إلى ينبع عبر مسار واضح يجمع المواقع والمنقولات والموعد، ويخضع لمراجعة الفريق قبل التنفيذ.','خطوات واضحة للنقل من الرياض إلى ينبع','في النطاق التجاري المعتمد للإطلاق، تظهر ينبع كوجهة مفعلة للطلبات المؤهلة التي يبدأ استلامها من الرياض. تظهر ينبع كوجهة للطلبات المؤهلة التي يبدأ استلامها من الرياض. يحدد العميل موقع التسليم بدقة ويصف الأثاث أو البضائع العامة والكميات وأي ملاحظة دخول، ثم يراجع الفريق المسافة والحمولة والموعد. يظل الطلب ضمن خدمة النقل البري العامة المعلنة ولا يمتد إلى خدمات أخرى غير معتمدة.','يدعم المسار نقل الأثاث والبضائع العامة المؤهلة من الرياض إلى ينبع. يمكن طلب التغليف أو التحميل والتنزيل، لكن تأكيدها يعتمد على مراجعة الحمولة والعنوانين والتوفر. النقل المحلي الذي يقع طرفاه داخل ينبع ليس ضمن نطاق الإطلاق المعلن حالياً، ولا تقدم الصفحة وعداً بخلاف ذلك.','تُراجع مواقع ينبع وفق عنوان الطلب الفعلي وشروط الدخول ووقوف المركبة. وجود المدينة في مناطق الخدمة لا يعني قبول مواقع مقيدة أو أنواع حمولة غير مدعومة.','[{"question":"هل يمكن طلب نقل من الرياض إلى ينبع؟","answer":"نعم، يمكن إرسال طلب مؤهل يبدأ من الرياض ويتجه إلى ينبع. يعتمد التأكيد على نوع المنقولات والعنوانين والموعد وتوفر الموارد بعد المراجعة.","displayOrder":10},{"question":"هل يتضمن نطاق الإطلاق النقل المحلي داخل ينبع؟","answer":"لا. النقل المحلي المعلن حالياً مخصص للطلبات التي يقع طرفاها في الرياض. تظهر ينبع كوجهة مفعلة للطلبات المؤهلة المنطلقة من الرياض.","displayOrder":20},{"question":"هل أحتاج إلى حساب لطلب النقل إلى ينبع؟","answer":"لا يلزم إنشاء حساب. يمكن إرسال الطلب المتجه إلى ينبع كزائر، ثم استخدام مرجع NQ ورقم الجوال في مسار التتبع المخصص.","displayOrder":30}]'::jsonb),
  ('YNB','en','General Goods and Furniture from Riyadh to Yanbu | Naqlk','Send a transport request from Riyadh to Yanbu through a clear flow covering locations, items, and timing before execution review.','A clear transport flow from Riyadh to Yanbu','In the approved launch scope, Yanbu is an enabled destination for eligible requests with pickup in Riyadh. Yanbu is an enabled destination for eligible requests collected in Riyadh. Customers identify the delivery point precisely and describe the furniture or general goods, quantities, and entry notes before distance, cargo, and timing are reviewed. The request remains within the published general road-transport service.','The flow supports eligible furniture and general-goods transport from Riyadh to Yanbu. Packing and loading or unloading may be requested, subject to cargo, address, and availability review. A local journey with both endpoints inside Yanbu is not in the currently published launch scope, and this page does not claim otherwise.','Yanbu locations are reviewed using the actual request address, entry conditions, and vehicle stopping needs. Service-area status does not imply acceptance of restricted sites or unsupported cargo types.','[{"question":"Can I request transport from Riyadh to Yanbu?","answer":"Yes. You can submit an eligible request originating in Riyadh and going to Yanbu. Confirmation depends on the cargo, addresses, date, and resources after review.","displayOrder":10},{"question":"Does the launch scope include local transport within Yanbu?","answer":"No. The published local service currently applies when both endpoints are in Riyadh. Yanbu is enabled as a destination for eligible requests originating in Riyadh.","displayOrder":20},{"question":"Do I need an account to request transport to Yanbu?","answer":"No account is required. You can submit the Yanbu request as a guest and use the NQ reference with the submitted mobile number in the dedicated tracking flow.","displayOrder":30}]'::jsonb),
  ('GIZ','ar','تنظيم طلب النقل من الرياض إلى جازان | نقلك','اطلب نقل أثاث أو بضائع مؤهلة من الرياض إلى جازان، مع مراجعة الحمولة والعنوانين والوصول قبل إرسال عرض سعر واضح من نقلك.','نقل الأثاث والبضائع من الرياض إلى جازان','في النطاق التجاري المعتمد للإطلاق، تظهر جازان كوجهة مفعلة للطلبات المؤهلة التي يبدأ استلامها من الرياض. تبدأ خدمة نقلك في جازان بطلب يوضح الحاجة بدلاً من وعد عام. يحدد العميل ما سينقله ومكان الاستلام والتسليم والتاريخ، ويضيف ملاحظات الوصول أو الصور عند الحاجة، ليتمكن الفريق من تقييم النطاق الفعلي.','يدعم المسار نقل الأثاث والبضائع العامة المؤهلة من الرياض إلى جازان. يمكن طلب التغليف أو التحميل والتنزيل، لكن تأكيدها يعتمد على مراجعة الحمولة والعنوانين والتوفر. النقل المحلي الذي يقع طرفاه داخل جازان ليس ضمن نطاق الإطلاق المعلن حالياً، ولا تقدم الصفحة وعداً بخلاف ذلك.','تعتمد إمكانية التنفيذ في جازان على العناوين المحددة والوصول وتوفر الموارد. لا تقدم الصفحة وعداً بتغطية كل موقع في المنطقة أو جميع الوجهات.','[{"question":"هل يمكن طلب نقل من الرياض إلى جازان؟","answer":"نعم، يمكن إرسال طلب مؤهل يبدأ من الرياض ويتجه إلى جازان. يعتمد التأكيد على نوع المنقولات والعنوانين والموعد وتوفر الموارد بعد المراجعة.","displayOrder":10},{"question":"هل يتضمن نطاق الإطلاق النقل المحلي داخل جازان؟","answer":"لا. النقل المحلي المعلن حالياً مخصص للطلبات التي يقع طرفاها في الرياض. تظهر جازان كوجهة مفعلة للطلبات المؤهلة المنطلقة من الرياض.","displayOrder":20},{"question":"هل يمكن إضافة التغليف لطلب متجه إلى جازان؟","answer":"يمكن اختيار التغليف عند تقديم الطلب المتجه إلى جازان. يراجع الفريق عدد القطع وطبيعتها، ولا يُدرج الدعم إلا كبند واضح في عرض السعر المعتمد.","displayOrder":30}]'::jsonb),
